export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = VALIDATORS[message.type];
  if (validator) {
    return validator(message);
  }
  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateLimit(limit: unknown): ValidationFailure | undefined {
  if (limit === undefined) return undefined;
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  return undefined;
}

function validateBefore(before: unknown): ValidationFailure | undefined {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }
  const obj = before as Record<string, unknown>;
  if (typeof obj.sessionId !== 'string' || obj.sessionId.length < 1 || obj.sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be a string of 1-128 characters'};
  }

  if (typeof obj.updatedAt !== 'string' && typeof obj.updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }

  const date = new Date(obj.updatedAt);
  if (!Number.isFinite(date.getTime())) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }
  return undefined;
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: Record<string, unknown> = { type: 'list_sessions' };

  const limitError = validateLimit(message.limit);
  if (limitError) return limitError;
  if (message.limit !== undefined) {
    result.limit = message.limit;
  }

  const beforeError = validateBefore(message.before);
  if (beforeError) return beforeError;
  if (message.before !== undefined) {
    const beforeObj = message.before as Record<string, unknown>;
    result.before = {
      sessionId: beforeObj.sessionId,
      updatedAt: beforeObj.updatedAt,
    };
  }

  return {
    valid: true,
    data: result as unknown as IncomingMessage,
  };
}

